Joyce: As more knowledge became available in previous centuries, the need for specialists to synthesize and explain it to nonspecialists increased. So computers will probably create a greater dependency on experts.$batch06$ AND q.prompt=$batch06$The dialogue most strongly supports the claim that Mary and Joyce disagree with each other about whether$batch06$ AND q.correct_choice=$batch06$B$batch06$) THEN RAISE EXCEPTION 'Question changed: PT112-S3-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT112-S3-Q4$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S3-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT112-S3-Q4$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Mary's Position$batch06$, $batch06$Computers will make it easier for ordinary people to gain knowledge without consulting experts.$batch06$), (1, $batch06$Joyce's Position$batch06$, $batch06$As knowledge has grown, the need for specialists to explain it has grown too, so computers will probably create more dependence on experts.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Both accept that computers will spread information. They split on what happens next: Mary says people will rely on experts less, Joyce says more.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether computers will increase people's need for experts.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT112-S3-Q4$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Both treat computers as spreading knowledge widely. Neither says the contribution will be negligible.$batch06$), ($batch06$B$batch06$, $batch06$Mary says computers will reduce reliance on experts. Joyce says they will increase it.$batch06$), ($batch06$C$batch06$, $batch06$Mary says it, and Joyce's whole argument starts from more knowledge being available.$batch06$), ($batch06$D$batch06$, $batch06$Dependence on *computers* is not the issue. Joyce is talking about dependence on *experts*.$batch06$), ($batch06$E$batch06$, $batch06$Neither says only computer experts can explain knowledge.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT112-S3-Q4$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
